exempt = (input('exempt_assets') || {})['CKV_AWS_19'] || []

control 'CKV_AWS_19' do
  title 'Ensure all data stored in the S3 bucket is securely encrypted at rest'

  desc <<~DESC
    Checkov asserts this against Terraform. This profile asserts it against
    the aws_s3_bucket resources that actually exist, read through the stock
    inspec-aws aws_s3_bucket resource.
  DESC

  desc 'rationale', <<~RATIONALE
    Default encryption is what makes an object written by any client
    encrypted at rest; without it, encryption depends on every writer
    remembering.
  RATIONALE

  desc 'check', <<~CHECK
    Checkov looks for: Ensure all data stored in the S3 bucket is securely
    encrypted at rest
  CHECK

  desc 'fix', <<~'FIX'
    Terraform — aws_s3_bucket:

      resource "aws_s3_bucket_server_side_encryption_configuration" "example" {
        bucket = aws_s3_bucket.example.id

        rule {
          apply_server_side_encryption_by_default {
            sse_algorithm     = "aws:kms"
            kms_master_key_id = aws_kms_key.s3.arn
          }
        }
      }

    Out of band — aws_s3_bucket:

      aws s3api put-bucket-encryption --bucket <name> \
        --server-side-encryption-configuration file://sse.json
  FIX

  tag checkov_id:            'CKV_AWS_19'
  tag checkov_category:      'ENCRYPTION'
  tag checkov_version:       '3.3.16'
  tag checkov_kind:          'graph'
  tag tf_resources:          %w[aws_s3_bucket aws_s3_bucket_server_side_encryption_configuration]
  tag tf_docs:               'https://registry.terraform.io/providers/hashicorp/aws/latest/docs/resources/s3_bucket'
  tag nist:                  ['SC-28', 'SC-28 (1)']
  tag nist_r4:               ['SC-28', 'SC-28 (1)']
  tag cci:                   ['CCI-001199', 'CCI-002475']
  tag ksi:                   ['KSI-SVC-CER']
  tag severity:              'high'
  tag severity_source:       'assessed'
  tag implementation_status: 'implemented'

